local ROOM_NUM_LEN = 8
local ViewBaseLayer = require("hall.NewViewBaseLayer")
local addNumberClub = class("addNumberClub", ViewBaseLayer)

function addNumberClub:ctor(callback, param)
    param = param or {}
    local csbPath = "hall/res/FriendScircle/addNumberClub.csb"
    addNumberClub.super.ctor(self, csbPath)
    self:enableMask(true)
    self.callback = callback
    self.param = param
    self.saveEnterNum = {}

    self.inputTxt = {}
    self.noInputTxt = {}

    for i = 1, 8 do
        self.inputTxt[i] = self.txtNode:getChildByName("Text_" .. i)
        self.noInputTxt[i] = self.txtNode1:getChildByName("Text_" .. i)
        self.inputTxt[i]:setString("")
        self.noInputTxt[i]:setString("0")
    end
    

    -- SCREEN_WIDTH = cc.Director:getInstance():getOpenGLView():getDesignResolutionSize().width
    -- SCREEN_HEIGHT = cc.Director:getInstance():getOpenGLView():getDesignResolutionSize().height
    -- self:setScale(SCREEN_WIDTH/1280,SCREEN_HEIGHT/720)
    -- self.tipStr:setString(param.tip or "")
	
	-- if param.curPoint then
	-- 	self.btnAddPartner_All:setVisible(true)
	-- else
	-- 	self.btnAddPartner_All:setVisible(false)
    -- end
    self:showRoomNum()
end

function addNumberClub:showRoomNum()
    local str = ""
    for i = 1, ROOM_NUM_LEN do
        if self.saveEnterNum[i] then
            self.inputTxt[i]:setString(self.saveEnterNum[i])
            self.noInputTxt[i]:setString("")
            str = str..self.saveEnterNum[i]
        else
            self.noInputTxt[i]:setString("0")
            self.inputTxt[i]:setString("")
        end
    end
    self.txt_num:setString(str)
end

function addNumberClub:onClickBtnNum1(sender, event)
    if #self.saveEnterNum < ROOM_NUM_LEN then
        table.insert(self.saveEnterNum, "1")
        self:showRoomNum()
    end
end

