function addNumberClub:onClickBtnDelete(sender, event)
    if #self.saveEnterNum > 0 then
        table.remove(self.saveEnterNum)
        self:showRoomNum()
    end
end

function addNumberClub:onClickBtnClose()
    self:removeSelf()
end

return addNumberClub